import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';
import 'package:pdf/pdf.dart';
import 'package:pdf/widgets.dart' as pw;
import 'package:printing/printing.dart';

class ReportsV2Page extends StatefulWidget { const ReportsV2Page({super.key}); @override State<ReportsV2Page> createState()=>_ReportsV2PageState(); }
class _ReportsV2PageState extends State<ReportsV2Page>{
 final db=FirebaseFirestore.instance; String report='Sales',period='Daily'; DateTime from=DateTime.now(),to=DateTime.now(); bool loading=true,retailUser=false,admin=false; String? assignedShopId,assignedShopName,shopId,productId,error; List<Map<String,dynamic>> rows=[],shops=[],products=[];
 List<String> get types=>retailUser?const ['Sales','Receipt','Payments','Party Ledger','Expenses','Cash Management','Stock Management']:(admin?const ['Sales','Receipt','Payments','Outstanding','Commission','Production','Expenses','Salary','Capital','Stock Management','Cash Management','Profit/Loss']:const ['Sales','Receipt','Payments','Outstanding','Commission','Production','Expenses','Salary','Capital','Stock Management','Cash Management']);
 CollectionReference<Map<String,dynamic>> collection(String n)=>db.collection('sharedData').doc('dailyHisab').collection(n);
 double number(dynamic v)=>v is num?v.toDouble():(double.tryParse('$v')??0);
 DateTime dateValue(dynamic v)=>v is Timestamp?v.toDate():(v is DateTime?v:(DateTime.tryParse('$v')??DateTime.fromMillisecondsSinceEpoch(0)));
 bool inRange(DateTime v)=>!v.isBefore(DateTime(from.year,from.month,from.day))&&!v.isAfter(DateTime(to.year,to.month,to.day,23,59,59));
 String dateText(DateTime v)=>'${v.day.toString().padLeft(2,'0')}-${v.month.toString().padLeft(2,'0')}-${v.year}'; String money(dynamic v)=>'₹${number(v).toStringAsFixed(2)}';
 @override void initState(){super.initState();_initialize();}
 Future<void> _initialize()async{try{final uid=FirebaseAuth.instance.currentUser?.uid;if(uid==null)throw StateError('Please login again.');final u=(await db.collection('users').doc(uid).get()).data()??{};retailUser=u['role']=='retail_shop_user';admin=u['role']=='admin';assignedShopId=u['shopId']?.toString();assignedShopName=u['shopName']?.toString();final p=await collection('products').get();products=p.docs.map((d)=>{'id':d.id,...d.data()}).where((x)=>x['active']!=false).toList();if(!retailUser){final s=await collection('retailShops').get();shops=s.docs.map((d)=>{'id':d.id,...d.data()}).where((x)=>x['active']!=false).toList();}if(!types.contains(report))report=types.first;if(mounted)setState((){loading=false;});await _load();}catch(e){if(mounted)setState((){error='$e';loading=false;});}}
 Future<List<Map<String,dynamic>>> fetch(String n,{String? shop})async{Query<Map<String,dynamic>> q=collection(n);if(retailUser&&shop!=null&&shop.isNotEmpty)q=q.where('shopId',isEqualTo:shop);final s=await q.get();return s.docs.map((d)=>{'id':d.id,...d.data()}).where((x)=>inRange(dateValue(x['date']))).toList();}
 void changePeriod(String v){final n=DateTime.now();DateTime a=n,b=n;if(v=='Monthly'){a=DateTime(n.year,n.month,1);b=DateTime(n.year,n.month+1,0);}else if(v=='Quarterly'){final m=((n.month-1)~/3)*3+1;a=DateTime(n.year,m,1);b=DateTime(n.year,m+3,0);}else if(v=='6 Monthly'){final m=n.month<=6?1:7;a=DateTime(n.year,m,1);b=DateTime(n.year,m+6,0);}else if(v=='Yearly'){a=DateTime(n.year,1,1);b=DateTime(n.year,12,31);}setState((){period=v;from=a;to=b;});_load();}
 Future<void> _load()async{if(!mounted)return;setState((){loading=true;error=null;});try{List<Map<String,dynamic>> r=[];if(report=='Sales'||report=='Outstanding'||report=='Commission'){r=await fetch('sales',shop:assignedShopId);if(!retailUser&&shopId!=null)r=r.where((x)=>x['shopId']?.toString()==shopId).toList();if(productId!=null)r=r.where((x){final i=x['items'];return i is List&&i.any((z)=>z is Map&&z['productId']?.toString()==productId);}).toList();if(report=='Outstanding')r=r.where((x)=>number(x['outstanding'])>0).toList();}else if(report=='Receipt'||report=='Payments'){r=await fetch('transactions',shop:assignedShopId);r=r.where((x)=>x['type']?.toString()==(report=='Receipt'?'Receipt':'Payment')).toList();}else if(report=='Party Ledger'){r=await fetch('transactions',shop:assignedShopId);r=r.where((x)=>(x['partyId']?.toString()??'').isNotEmpty).map((x)=>{...x,'signedAmount':x['type']=='Receipt'?number(x['amount']):-number(x['amount'])}).toList();}else if(report=='Expenses'){r=await fetch(retailUser?'transactions':'productionExpenses',shop:assignedShopId);if(retailUser)r=r.where((x)=>x['type']=='Payment'&&x['subType']=='Expense').toList();}else if(report=='Production')r=await fetch('production');else if(report=='Salary')r=await fetch('salary');else if(report=='Capital')r=await fetch('capital');else if(report=='Cash Management')r=await _cash();else if(report=='Stock Management')r=await _stock();else if(report=='Profit/Loss')r=await _profit();r.sort((a,b)=>dateValue(b['date']).compareTo(dateValue(a['date'])));if(mounted)setState((){rows=r;loading=false;});}catch(e){if(mounted)setState((){error='$e';loading=false;});}}
 Future<List<Map<String,dynamic>>> _cash()async{final r=<Map<String,dynamic>>[];final t=await fetch('transactions',shop:assignedShopId),s=await fetch('sales',shop:assignedShopId);for(final x in t){final a=number(x['amount']);final typ=x['type']?.toString()??'';final sign=typ=='Receipt'?1:(typ=='Payment'||typ=='Commission Payment'?-1:0);r.add({'date':x['date'],'particular':'$typ • ${x['partyName']??x['description']??''}','amount':a,'signedAmount':a*sign,'account':x['account']??x['paymentAccount']??x['paymentMode']??'Cash'});}for(final x in s){final a=number(x['paymentReceived']);if(a>0)r.add({'date':x['date'],'particular':'Sales • ${x['shopName']??assignedShopName??''}','amount':a,'signedAmount':a,'account':x['account']??x['paymentAccount']??x['paymentMode']??'Cash'});}return r;}
 Future<List<Map<String,dynamic>>> _stock()async{final r=<Map<String,dynamic>>[];final tr=await fetch('stockTransfers',shop:assignedShopId),s=await fetch('sales',shop:assignedShopId);for(final p in products){final pid=p['id'].toString();final incoming=tr.where((x)=>x['productId']?.toString()==pid).fold(0.0,(a,x)=>a+number(x['quantity']));double sold=0;for(final sale in s){final items=sale['items'];if(items is List)for(final i in items){if(i is Map&&i['productId']?.toString()==pid)sold+=number(i['quantity']);}}r.add({'date':DateTime.now(),'particular':'${retailUser?(assignedShopName??'Shop'):'Stock'} • ${p['name']??pid}','quantity':incoming-sold});}return r;}
 Future<List<Map<String,dynamic>>> _profit()async{final s=await fetch('sales'),e=await fetch('productionExpenses'),w=await fetch('salary');final gross=s.fold(0.0,(a,x)=>a+number(x['grossAmount'])),comm=s.fold(0.0,(a,x)=>a+number(x['commission'])),exp=e.fold(0.0,(a,x)=>a+number(x['amount'])),sal=w.fold(0.0,(a,x)=>a+number(x['amount']));return [{'particular':'Gross Sales','amount':gross},{'particular':'Commission','amount':comm},{'particular':'Expenses','amount':exp},{'particular':'Salary','amount':sal},{'particular':'Profit / Loss','amount':gross-comm-exp-sal}];}
 String particular(Map<String,dynamic>x)=>'${x['particular']??x['partyName']??x['productName']??x['type']??''}';double amount(Map<String,dynamic>x)=>number(x['signedAmount']??x['amount']??x['grossAmount']??x['netAmount']??x['quantity']);double get total=>rows.fold(0.0,(s,x)=>s+amount(x));
 Future<void> exportPdf()async{if(rows.isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('No report data to export.')));return;}await Printing.layoutPdf(onLayout:(format)async{final d=pw.Document();d.addPage(pw.MultiPage(pageFormat:PdfPageFormat.a4,build:(_)=>[pw.Text('DAILY HISAB - $report REPORT',style:pw.TextStyle(fontSize:18,fontWeight:pw.FontWeight.bold)),pw.Text('Period: ${dateText(from)} to ${dateText(to)}'),pw.SizedBox(height:10),pw.TableHelper.fromTextArray(headers:const ['Date','Particular','Amount'],data:rows.map((x)=>[dateText(dateValue(x['date'])),particular(x),amount(x).toStringAsFixed(2)]).toList()),pw.Text('Total: ${total.toStringAsFixed(2)}')]);return d.save();});}
 @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Reports'),actions:[IconButton(onPressed:loading?null:exportPdf,icon:const Icon(Icons.picture_as_pdf))]),body:ListView(padding:const EdgeInsets.all(16),children:[DropdownButtonFormField<String>(initialValue:report,decoration:const InputDecoration(labelText:'Report',border:OutlineInputBorder()),items:types.map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v){if(v!=null){setState(()=>report=v);_load();}}),const SizedBox(height:10),DropdownButtonFormField<String>(initialValue:period,decoration:const InputDecoration(labelText:'Period',border:OutlineInputBorder()),items:const ['Daily','Monthly','Quarterly','6 Monthly','Yearly'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v){if(v!=null)changePeriod(v);}),if(!retailUser&&report=='Sales')... [const SizedBox(height:10),DropdownButtonFormField<String>(initialValue:shopId,decoration:const InputDecoration(labelText:'Retail Shop',border:OutlineInputBorder()),items:[const DropdownMenuItem<String>(value:null,child:Text('All Shops')),...shops.map((x)=>DropdownMenuItem<String>(value:x['id'].toString(),child:Text(x['name']?.toString()??x['id'].toString())))],onChanged:(v){setState(()=>shopId=v);_load();})],if(report=='Sales')... [const SizedBox(height:10),DropdownButtonFormField<String>(initialValue:productId,decoration:const InputDecoration(labelText:'Product',border:OutlineInputBorder()),items:[const DropdownMenuItem<String>(value:null,child:Text('All Products')),...products.map((x)=>DropdownMenuItem<String>(value:x['id'].toString(),child:Text(x['name']?.toString()??x['id'].toString())))],onChanged:(v){setState(()=>productId=v);_load();})],const SizedBox(height:14),if(error!=null)Text(error!,style:const TextStyle(color:Colors.red)),if(loading)const Center(child:CircularProgressIndicator())else if(rows.isEmpty)const Padding(padding:EdgeInsets.all(24),child:Text('No data for selected period.'))else Card(child:Column(children:[ListTile(title:Text('$report Report',style:const TextStyle(fontWeight:FontWeight.bold)),trailing:Text('Total ${money(total)}')),const Divider(height:1),...rows.take(100).map((x)=>ListTile(dense:true,title:Text(particular(x)),subtitle:Text(dateText(dateValue(x['date']))),trailing:Text(money(amount(x)))))]))]);
}
